		{"1.0.0-rc1", "1.0.0", true, "prerelease in current"},
		{"1.0.0", "1.0.1-rc1", true, "prerelease in latest is still newer"},
		{"1.0.0-dev-xxx", "1.0.1", false, "dev build skips version check"},

